ORDER = 'https://publication.pravo.gov.ru/document/0001202606020025'
MEA = 'https://www.mea.gov.in/ras'

INTRO = {
 'ru': ('Для бизнеса', 'Российское право для международного найма',
        'Помогаем работодателям и зарубежным агентствам выстроить правовой маршрут привлечения иностранных работников в Россию: от анализа проекта до документов, уведомлений и проверки рисков.'),
 'en': ('For business', 'Russian immigration counsel for cross-border hiring',
        'Legal support for Russian employers and overseas recruitment agencies bringing foreign workers to Russia. We map the route, review documents and allocate responsibilities before applications begin.'),
 'fr': ('Pour les entreprises', 'Un parcours juridique pour le recrutement international',
        'SalutRussie accompagne l’analyse juridique des projets d’emploi de travailleurs étrangers en Russie. Deux parcours sont proposés aux employeurs et aux agences de recrutement étrangères.'),
}

PAGES = {
 'employers': {
  'ru': ('Российским работодателям', 'Проверка правового маршрута, разрешений, документов и обязанностей после найма.', '''
  <section class="sr-sec"><div class="sr-width"><div class="sr-section-head"><h2>Сначала определяем модель найма</h2><p>Правила зависят от гражданства работника, его статуса, региона и характера работы, роли работодателя и типа договора. До подачи документов мы сопоставляем эти факты с действующими требованиями и определяем, какие разрешения или исключения нужно проверить.</p></div>
  <div class="sr-steps"><div class="sr-step"><b>01</b><h3>Карта проекта</h3><p>Вакансии, количество людей, место работы, сроки, стороны договора и предполагаемые страны подбора.</p></div><div class="sr-step"><b>02</b><h3>Правовая стратегия</h3><p>Категории работников, возможные разрешения, последовательность действий и критические зависимости.</p></div><div class="sr-step"><b>03</b><h3>Документы</h3><p>Проверка сведений работодателя и кандидатов, подготовка заявлений и согласование обязанностей сторон.</p></div><div class="sr-step"><b>04</b><h3>После въезда</h3><p>Контроль миграционного учёта, договоров, уведомлений и изменений статуса в согласованном объёме.</p></div></div></div></section>
  <section class="sr-sec alt"><div class="sr-width"><div class="sr-section-head"><h2>Что входит в юридическую работу</h2></div><div class="sr-grid"><div class="sr-card"><h3>Разрешения и визы</h3><p>Определяем применимые процедуры привлечения работников, разрешений на работу, приглашений и виз. Проверяем исключения до выбора маршрута.</p></div><div class="sr-card"><h3>Уведомления МВД</h3><p>Проверяем событие, адресата, актуальную форму, способ и срок подачи. Сохраняем доказательства направления и получения.</p></div><div class="sr-card"><h3>Аудит рисков</h3><p>Сопоставляем фактическую работу с договорами, статусами, адресами и документами. Готовим список исправлений по приоритету.</p></div></div></div></section>
  <section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>Что понадобится для первого разбора</h2><table><caption>Отправляйте чувствительные документы только после согласования безопасного канала</caption><thead><tr><th>От работодателя</th><th>О работниках и проекте</th></tr></thead><tbody><tr><td>Организация, регион и место фактической работы</td><td>Гражданство, количество и предполагаемый статус</td></tr><tr><td>Должности, график, тип договора, принимающая сторона</td><td>Планируемые сроки, место подачи и въезда</td></tr><tr><td>Что уже оформлено и какие решения получены</td><td>Расхождения в документах и прежние отказы, если есть</td></tr></tbody></table><h2>Частые вопросы</h2><details><summary>Всегда ли работодателю нужно разрешение на привлечение?</summary><p>Нет универсального ответа: сначала определяют категорию работника и применимые исключения. Решение для одного гражданства или статуса нельзя автоматически переносить на других.</p></details><details><summary>Можно ли подготовить одно уведомление на всю группу?</summary><p>Порядок и форма зависят от события и действующих правил. Мы проверяем требование по каждому договору и фиксируем подтверждение подачи.</p></details><details><summary>Гарантируете выдачу разрешений или виз?</summary><p>Нет. Решения принимают уполномоченные органы. Мы отвечаем за согласованный объём правовой работы и сообщаем о выявленных рисках.</p></details><p class="sr-meta">Правовая отправная точка: <a href="LAW">ФЗ № 115-ФЗ, статья 13</a> и <a href="ORDER">приказ МВД № 290 от 12.05.2026</a> о формах уведомлений. Редакция и применимость проверяются на дату обращения.</p></div></section>'''),
  'en': ('For Russian employers', 'Legal route mapping, documents and post-hire compliance for foreign staff.', '''
  <section class="sr-sec"><div class="sr-width"><div class="sr-section-head"><h2>Define the hiring route before filing</h2><p>The process depends on nationality, immigration status, job location, the employer’s role and the contract. We review those facts before identifying possible permits, exemptions and filing steps.</p></div><div class="sr-steps"><div class="sr-step"><b>01</b><h3>Project brief</h3><p>Roles, headcount, location, target dates, source countries and contracting parties.</p></div><div class="sr-step"><b>02</b><h3>Legal route</h3><p>Worker categories, potential permissions, dependencies and material risks.</p></div><div class="sr-step"><b>03</b><h3>Documents</h3><p>Review of employer and candidate information, applications and agreed responsibilities.</p></div><div class="sr-step"><b>04</b><h3>After arrival</h3><p>Agreed support for migration registration, contracts, notifications and status changes.</p></div></div></div></section>
  <section class="sr-sec alt"><div class="sr-width"><div class="sr-section-head"><h2>Where we can help</h2></div><div class="sr-grid"><div class="sr-card"><h3>Permits and visas</h3><p>Assess the applicable route for engaging foreign staff, work authorisation, invitations and visas, including exceptions.</p></div><div class="sr-card"><h3>Ministry notifications</h3><p>Check the event, competent office, current form, filing method and deadline; organise evidence of submission.</p></div><div class="sr-card"><h3>Risk review</h3><p>Compare actual work with contracts, immigration status, work location and records, then prioritise corrective steps.</p></div></div></div></section>
  <section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>What to include in an initial brief</h2><table><caption>Please agree a secure channel before sending sensitive documents</caption><thead><tr><th>Employer</th><th>People and project</th></tr></thead><tbody><tr><td>Entity, region and actual worksite</td><td>Nationalities, headcount and expected status</td></tr><tr><td>Roles, schedule, contract model and host</td><td>Target dates, application location and arrival plan</td></tr><tr><td>Approvals already obtained or refused</td><td>Document discrepancies or previous refusals</td></tr></tbody></table><h2>Frequently asked questions</h2><details><summary>Does every employer need the same permit?</summary><p>No single route fits every worker. The legal category and any exemptions must be assessed before filing.</p></details><details><summary>Can one notification cover a whole group?</summary><p>We check the current requirement for each contract and event, then retain proof of the filing. Do not assume a group filing is sufficient.</p></details><details><summary>Do you guarantee permits or visas?</summary><p>No. Government authorities decide applications. Our work is limited to the agreed legal scope and risk advice.</p></details><p class="sr-meta">Starting points: <a href="LAW">Federal Law No. 115-FZ, Article 13</a> and <a href="ORDER">Ministry of Internal Affairs Order No. 290 of 12 May 2026</a>. Current versions and applicability require checking for each matter.</p></div></section>'''),
  'fr': ('Employeurs en Russie', 'Stratégie juridique et contrôle des documents pour l’emploi de travailleurs étrangers.', '''<section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>Commencer par les faits</h2><p>Nationalité, statut migratoire, lieu de travail, employeur et type de contrat déterminent les démarches à vérifier. Nous analysons la voie juridique, les autorisations éventuelles, les documents et les obligations après l’arrivée.</p><h2>Notre intervention</h2><ol><li>Définir le projet et répartir les responsabilités.</li><li>Vérifier permis, invitations et visas applicables.</li><li>Contrôler les dossiers et les notifications au ministère de l’Intérieur.</li><li>Examiner les risques liés aux contrats, au lieu de travail et au séjour.</li></ol><p class="sr-meta">Sources de départ : <a href="LAW">loi fédérale n° 115-FZ, article 13</a> et <a href="ORDER">arrêté du ministère de l’Intérieur n° 290 du 12 mai 2026</a>. Les règles en vigueur sont vérifiées dossier par dossier.</p></div></section>'''),
 },
 'recruitment-partners': {
  'ru': ('Зарубежным рекрутинговым агентствам', 'Российский юридический партнёр для проектов привлечения работников.', '''<section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>Соединяем подбор и правовой маршрут в России</h2><p>Если ваше агентство подбирает кандидатов для российского работодателя, правовые действия в России нужно планировать до обещания даты выхода на работу. Мы можем выступать российским юридическим партнёром: оценить модель, составить карту документов и сопровождать согласованные миграционные процедуры. Подбор кандидатов и решения государственных органов остаются за соответствующими участниками.</p><div class="sr-grid"><div class="sr-card"><h3>Агентство</h3><p>Подбор, проверка квалификации и готовности кандидатов, взаимодействие с ними и соблюдение правил страны отправления.</p></div><div class="sr-card"><h3>Работодатель</h3><p>Вакансии, условия работы, договор, принимающая сторона и исполнение обязанностей в России.</p></div><div class="sr-card"><h3>SalutRussie</h3><p>Правовая оценка российской части, список документов, сопровождение согласованных заявлений и контроль миграционных рисков.</p></div></div><h2>Как начать партнёрство</h2><ol><li>Направьте краткий профиль агентства и сведения о регистрации без персональных данных кандидатов.</li><li>Опишите работодателя, вакансии, регион, количество людей и предполагаемые сроки.</li><li>Мы определим вопросы для правовой проверки и разграничим задачи сторон.</li><li>После согласования объёма работ составим рабочую карту документов и событий.</li></ol><h2>Особенно для агентств из Индии</h2><p>Индийская сторона должна самостоятельно проверить применимые правила зарубежного трудоустройства и свой статус. Отправная точка — <a href="MEA">страница МИД Индии о регистрации Recruiting Agents</a>. Российский маршрут проверяется отдельно; наличие индийской регистрации само по себе не заменяет российские разрешения и уведомления.</p><h2>Частые вопросы</h2><details><summary>Может ли агентство обещать кандидату дату выезда?</summary><p>До проверки правового маршрута, документов и решений уполномоченных органов такую дату нельзя считать гарантированной.</p></details><details><summary>Берёте ли вы подбор работников на себя?</summary><p>Эта страница посвящена российской юридической части. Роли в подборе и коммуникации с кандидатами распределяются отдельно.</p></details><p class="sr-meta">Российская правовая основа для анализа: <a href="LAW">ФЗ № 115-ФЗ</a> и <a href="ORDER">приказ МВД № 290 от 12.05.2026</a>. Конкретный маршрут зависит от статуса работников и модели договора.</p></div></section>'''),
  'en': ('For overseas recruitment agencies', 'A Russian legal partner for international worker placement projects.', '''<section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>Connect recruitment with the Russian legal route</h2><p>If your agency sources candidates for a Russian employer, the immigration process should be mapped before a start date is promised. SalutRussie can act as Russian legal counsel: review the structure, document the route and support the agreed immigration filings. Candidate sourcing and government decisions remain with the relevant parties.</p><div class="sr-grid"><div class="sr-card"><h3>Recruitment agency</h3><p>Candidate sourcing, skills checks, communication and compliance with rules in the country of origin.</p></div><div class="sr-card"><h3>Russian employer</h3><p>Vacancies, employment terms, contracts, worksite and the employer’s obligations in Russia.</p></div><div class="sr-card"><h3>SalutRussie</h3><p>Russian legal assessment, document map, support with agreed applications and immigration risk review.</p></div></div><h2>Start with a short project brief</h2><ol><li>Share the agency profile and registration details without candidate personal data.</li><li>Describe the employer, roles, worksite, headcount and intended dates.</li><li>We identify the legal questions and agree who handles each task.</li><li>Once scope is agreed, we prepare a document and decision map.</li></ol><h2>For agencies in India</h2><p>Check your status and the applicable Indian overseas recruitment rules independently. The <a href="MEA">Indian Ministry of External Affairs guidance on Recruiting Agents</a> is a useful starting point. Indian registration does not replace Russian immigration permissions or notifications; the Russian route needs a separate review.</p><h2>Frequently asked questions</h2><details><summary>Can we promise candidates a departure date?</summary><p>A date should not be treated as guaranteed before the route, documents and authority decisions are checked.</p></details><details><summary>Will you recruit candidates?</summary><p>This page covers Russian legal work. Recruitment and candidate communication are allocated separately in the project scope.</p></details><p class="sr-meta">Russian starting points: <a href="LAW">Federal Law No. 115-FZ</a> and <a href="ORDER">Ministry Order No. 290 of 12 May 2026</a>. The route depends on status and contract structure.</p></div></section>'''),
  'fr': ('Agences de recrutement étrangères', 'Un partenaire juridique en Russie pour vos projets de mobilité professionnelle.', '''<section class="sr-sec"><div class="sr-width sr-b2b-copy"><h2>Répartir les rôles avant les démarches</h2><p>L’agence sélectionne les candidats et vérifie ses obligations dans le pays de départ. L’employeur définit les postes et les conditions. SalutRussie peut analyser le parcours juridique russe, établir la liste des documents et accompagner les démarches convenues.</p><ol><li>Présentez l’agence et sa situation réglementaire, sans données personnelles de candidats.</li><li>Décrivez l’employeur, les postes, le lieu de travail et le calendrier envisagé.</li><li>Nous examinons la voie juridique et répartissons les tâches avant tout engagement.</li></ol><p>Pour les agences en Inde, consultez les <a href="MEA">règles du ministère indien des Affaires étrangères sur les Recruiting Agents</a>. Une vérification distincte est nécessaire en Russie.</p><p class="sr-meta">Sources russes : <a href="LAW">loi fédérale n° 115-FZ</a> et <a href="ORDER">arrêté ministériel n° 290 du 12 mai 2026</a>.</p></div></section>'''),
 },
}


def get_page(lang, part):
    if part == 'index':
        label, title, desc = INTRO[lang]
        names = {
            'ru': ('Российским работодателям', 'Зарубежным рекрутинговым агентствам', 'Карта правового маршрута', 'Разделяем обязанности сторон, проверяем документы и риски до подачи.', 'Обсудить проект'),
            'en': ('Russian employers', 'Overseas recruitment agencies', 'A clear legal route', 'Define responsibilities, documents and risks before applications begin.', 'Discuss a project'),
            'fr': ('Employeurs en Russie', 'Agences de recrutement étrangères', 'Un parcours vérifié', 'Répartir les responsabilités et vérifier les documents avant les demandes.', 'Parler du projet'),
        }[lang]
        body = f'''<section class="sr-sec"><div class="sr-width"><div class="sr-grid"><a class="sr-card" href="/{lang}/for-business/employers/"><span class="sr-icon" aria-hidden="true">§</span><h2>{names[0]}</h2><p>{'Permits, documents, notifications and risk review.' if lang=='en' else 'Разрешения, документы, уведомления и аудит рисков.' if lang=='ru' else 'Autorisations, documents, notifications et risques.'}</p><span class="sr-link">{'Подробнее' if lang=='ru' else 'Learn more' if lang=='en' else 'En savoir plus'} →</span></a><a class="sr-card" href="/{lang}/for-business/recruitment-partners/"><span class="sr-icon" aria-hidden="true">↗</span><h2>{names[1]}</h2><p>{'Russian legal support for cross-border hiring, including agencies in India.' if lang=='en' else 'Российское правовое сопровождение международного найма, в том числе для агентств из Индии.' if lang=='ru' else 'Accompagnement juridique russe, notamment pour les agences en Inde.'}</p><span class="sr-link">{'Подробнее' if lang=='ru' else 'Learn more' if lang=='en' else 'En savoir plus'} →</span></a></div></div></section><section class="sr-sec alt"><div class="sr-width"><div class="sr-section-head"><h2>{names[2]}</h2><p>{names[3]}</p></div><div class="sr-steps"><div class="sr-step"><b>01</b><h3>{'Бриф' if lang=='ru' else 'Brief'}</h3></div><div class="sr-step"><b>02</b><h3>{'Правовая оценка' if lang=='ru' else 'Legal review' if lang=='en' else 'Analyse juridique'}</h3></div><div class="sr-step"><b>03</b><h3>{'План документов' if lang=='ru' else 'Document plan' if lang=='en' else 'Plan documentaire'}</h3></div><div class="sr-step"><b>04</b><h3>{'Сопровождение' if lang=='ru' else 'Agreed support' if lang=='en' else 'Accompagnement'}</h3></div></div></div></section>'''
        return label, title, desc, body
    title, desc, body = PAGES[part][lang]
    for key, value in [('LAW', LAW), ('ORDER', ORDER), ('MEA', MEA)]:
        body = body.replace(f'"{key}"', f'"{escape(value, quote=True)}"')
    label = {'ru': 'ДЛЯ БИЗНЕСА', 'en': 'FOR BUSINESS', 'fr': 'POUR LES ENTREPRISES'}[lang]
    return label, title, desc, body
